from collections import deque


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._next_id = 1
        # Priority queues keyed by (vip, priority_level)
        # We'll use a dict of deques, where vip=True levels come first
        self._queues = {}
        for vip in (True, False):
            for level in range(len(self.PRIORITIES)):
                self._queues[(vip, level)] = deque()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = {"vip": vip}

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty.")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer}")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority}")

        ticket_id = self._next_id
        self._next_id += 1

        is_vip = self._customers[customer]["vip"]
        level = self.PRIORITIES.index(priority)

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "vip": is_vip,
            "open": True,
        }
        self._queues[(is_vip, level)].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        # VIP tickets first (True before False), then priority high->low
        for vip in (True, False):
            for level in range(len(self.PRIORITIES) - 1, -1, -1):
                q = self._queues[(vip, level)]
                while q:
                    tid = q.popleft()
                    ticket = self._tickets.get(tid)
                    if ticket and ticket["open"]:
                        return tid
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        self._tickets[ticket_id]["open"] = False

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        ticket = self._tickets[ticket_id]
        if ticket["open"]:
            return
        ticket["open"] = True
        is_vip = ticket["vip"]
        level = self.PRIORITIES.index(ticket["priority"])
        # Reinsert at the end of its queue — but to maintain opening order
        # we can rely on the fact that reopen isn't specified for ordering
        # beyond "back into the queue". We'll append here.
        self._queues[(is_vip, level)].append(ticket_id)
